/* =====================================================================
   SAVE
   ===================================================================== */
const SAVE_KEY = 'neonspeed_save_v2', GHOST_KEY = 'neonspeed_ghost_v2';
const store = {
  get(k) { try { return localStorage.getItem(k); } catch (e) { return null; } },
  set(k, v) { try { localStorage.setItem(k, v); } catch (e) {} },
  del(k) { try { localStorage.removeItem(k); } catch (e) {} },
};
function defaultSave() {
  return {
    coins: 0, highScore: 0, bestDist: 0, bestCombo: 0,
    owned: ['red'], selected: 'red',
    upgrades: { engine: 0, handling: 0, nitro: 0, magnet: 0 },
    settings: { music: true, sfx: true, quality: IS_TOUCH ? 'low' : 'high', reducedMotion: false, haptics: true },
    nickname: 'RACER', tutorialDone: false, challengeHistory: [], avatar: 'rookie', badges: {},
    stats: { runs: 0, totalDist: 0, nearMisses: 0, coinsTotal: 0, escapes: 0, bestKmh: 0, challengeWins: 0, edgesTotal: 0 },
    missions: null,
  };
}
function loadSave() {
  const d = defaultSave();
  let s = null;
  try { s = JSON.parse(store.get(SAVE_KEY)); } catch (e) {}
  if (!s) {
    // Migrate progress from the previous version of the game
    const lc = parseInt(store.get('dd_coins')) || 0, lh = parseInt(store.get('dd_highscore')) || 0;
    const lsel = (store.get('dd_selected') || '').toLowerCase();
    d.coins = lc; d.highScore = lh;
    CARS.forEach(c => {
      if (c.legacy <= lh && !d.owned.includes(c.id)) d.owned.push(c.id);
      if (lsel && c.hex === lsel && d.owned.includes(c.id)) d.selected = c.id;
    });
    return d;
  }
  return Object.assign(d, s, {
    upgrades: Object.assign(d.upgrades, s.upgrades || {}),
    settings: Object.assign(d.settings, s.settings || {}),
    stats: Object.assign(d.stats, s.stats || {}),
    badges: Object.assign({}, s.badges || {}),
  });
}
let save = loadSave();
const persist = () => store.set(SAVE_KEY, JSON.stringify(save));

function todayKey() { const d = new Date(); return d.getFullYear() + '-' + (d.getMonth() + 1) + '-' + d.getDate(); }
function seeded(seed) { return function () { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
function ensureMissions() {
  const key = todayKey();
  if (save.missions && save.missions.date === key && save.missions.v === MISSION_V) return;
  let h = 0; for (const ch of key) h = (h * 31 + ch.charCodeAt(0)) | 0;
  const r = seeded(h);
  const list = [];
  const draw = (pool, n) => { for (let k = 0; k < n && pool.length; k++) {
    const t = pool.splice(Math.floor(r() * pool.length), 1)[0];
    list.push({ tid: t.id, tier: Math.min(2, Math.floor(r() * 3)), progress: 0, claimed: false });
  } };
  draw(MISSION_TPL.filter(t => !t.w), DAILY_N);
  MISSION_WORLDS.forEach(w => draw(MISSION_TPL.filter(t => t.w === w), WORLD_N));
  save.missions = { date: key, v: MISSION_V, list };
  persist();
}
const tplOf = m => MISSION_TPL.find(t => t.id === m.tid);
const missionGoal = m => tplOf(m).goals[m.tier];
const missionText = m => tplOf(m).text.replace('{n}', fmt(missionGoal(m))).replace(' 1 times', ' once').replace(/ 1 (helicopter|roadblock|fork)s/, ' 1 $1');
const missionReward = m => Math.round(MISSION_REWARD[m.tier] * (tplOf(m).w ? 1.5 : 1));
const missionActive = m => { const w = tplOf(m).w; return !w || (typeof WORLD === 'object' && WORLD.id === w); };
const claimableCount = () => { ensureMissions(); return save.missions.list.filter(m => !m.claimed && m.progress >= missionGoal(m)).length; };

function perf(setup = null) {
  const id = setup ? setup.car : save.selected, c = carById(id).st, u = setup ? setup.upgrades : save.upgrades;
  const T = traitOf(id), tn = setup ? sanitizeTune(setup.tune) : tuneOf(id), ty = tn.tires, gr = tn.gears;
  return {
    maxSpeed: 52 * (1 + 0.035 * (c.speed + u.engine)) * (1 - 0.01 * u.handling) * (ty === 'rain' ? 0.97 : 1) * (gr === 'short' ? 0.95 : gr === 'long' ? 1.05 : 1),
    accel: 15 * (1 + 0.05 * (c.speed + u.engine)) * T.accel * (gr === 'short' ? 1.15 : gr === 'long' ? 0.85 : 1),
    handling: (1 + 0.07 * (c.handling + u.handling)) * (1 - 0.02 * u.engine) * (ty === 'slick' ? 1.07 : 1),
    wet: T.wet * (1 - 0.03 * u.engine) * (ty === 'slick' ? 0.65 : ty === 'rain' ? 1.3 : 1),
    mass: T.mass, width: T.width,
    nitroDrain: 24 * (1 - 0.06 * (c.nitro + u.nitro)) * T.drain,
    nitroBoost: 1.42 + 0.02 * (c.nitro + u.nitro) + T.boost,
    regen: 3.5 * (1 - 0.08 * u.nitro),
    puTime: 1 + 0.15 * u.magnet, puGap: 1 + 0.05 * u.magnet,
    flame: FLAME_COLS[tn.flame] || FLAME_COLS.blue,
  };
}
function playerLevel() {
  const km = save.stats.totalDist / 1000;
  const f = Math.sqrt(km / 1.5) + 1;
  return { level: Math.floor(f), pct: (f - Math.floor(f)) * 100 };
}


