function makeEnv(night) {
  // Small gradient cube map: works on every GPU (no float render targets needed)
  const top = night ? '#070a22' : '#3d86e0', hor = night ? '#3a1d70' : '#dcefff', bot = night ? '#0a0812' : '#5d6a5e';
  const face = (kind, i) => {
    const c = document.createElement('canvas'); c.width = c.height = 64; const x = c.getContext('2d');
    if (kind === 'top') { x.fillStyle = top; x.fillRect(0, 0, 64, 64); }
    else if (kind === 'bot') { x.fillStyle = bot; x.fillRect(0, 0, 64, 64); }
    else {
      const g = x.createLinearGradient(0, 0, 0, 64); g.addColorStop(0, top); g.addColorStop(0.5, hor); g.addColorStop(0.56, bot); g.addColorStop(1, bot);
      x.fillStyle = g; x.fillRect(0, 0, 64, 64);
      if (night) { x.fillStyle = ['#00f0ff', '#ff2bd6', '#ffd98a', '#9b5cff'][i]; x.fillRect(10 + i * 9, 26, 22, 4); x.fillRect(40 - i * 5, 20, 10, 3); }
      else if (i === 0) { x.fillStyle = '#ffffff'; x.beginPath(); x.arc(32, 14, 7, 0, 7); x.fill(); }
    }
    return c;
  };
  const t = new THREE.CubeTexture([face('side', 0), face('side', 1), face('top'), face('bot'), face('side', 2), face('side', 3)]);
  t.colorSpace = THREE.SRGBColorSpace; t.needsUpdate = true;
  return t;
}
