    if (style === 'hatch' || style === 'krait') sh.lineTo(L - 0.18, H + 0.04);
    else sh.lineTo(L - 0.5, H + 0.02);
    sh.lineTo(-0.85, H);
    sh.lineTo(-L + 0.35, H - 0.17);
    sh.quadraticCurveTo(-L - 0.06, H - 0.21, -L - 0.05, 0.52);
    sh.lineTo(-L + 0.06, 0.34);
