/* ---------- Truck ---------- */
function buildTruckProc() {
  const root = new THREE.Group(), body = new THREE.Group(); root.add(body);
  const cabM = paint(pick([0xd62828, 0x1d4ed8, 0xf2f2f2, 0x2f855a, 0xf59e0b]), false);
  const trailerM = paint(pick([0xe8e6df, 0xd9dde3, 0x9aa3ad, 0xf1efe8]), false);
  const stripeM = paint(pick([0x34c3ef, 0x007bff, 0xf2c744, 0xf14d4d]), false);
  const add = (key, m, cast = true) => { const me = new THREE.Mesh(merged('truck' + key, TRUCK_GEO[key]), m); me.castShadow = cast; body.add(me); return me; };
  add('cab', cabM); add('trailer', trailerM); add('stripe', stripeM, false); add('trim', MAT.trim, false); add('glass', MAT.glass, false);
  const tail = add('tail', MAT.tail, false);
  const wheels = [];
  [[-3.4, true], [0.4, false], [2.6, false], [3.5, false]].forEach(([z, f]) => {
    [-1.08, 1.08].forEach(x => { const w = wheel(x, 0.45, z, f, 1.25); root.add(w.steer); wheels.push(w); });
  });
  blob(root, 3.3, 10.5);
  return { root, body, wheels, tailMesh: tail, halfW: 1.23, halfL: 4.4, lights: { tailZ: 4.5, tailX: 0.85, tailY: 0.75, single: false } };
}
