/* =====================================================================
   POST-PROCESSING: bloom, colour grade, vignette, speed blur, aberration
   Self-made (no extra libraries). Quality adapts to the device.
   ===================================================================== */
const Post = (() => {
  const VS = 'varying vec2 vUv; void main(){ vUv = uv; gl_Position = vec4(position.xy, 0.0, 1.0); }';
  const mat = (fs, uniforms) => new THREE.ShaderMaterial({ uniforms, vertexShader: VS, fragmentShader: fs, depthTest: false, depthWrite: false });
  const bright = mat(`uniform sampler2D tDiffuse; uniform float threshold, knee; varying vec2 vUv;
    void main(){ vec4 t4 = texture2D(tDiffuse, vUv); vec3 c = t4.rgb * clamp(t4.a, 0.0, 1.0); float l = max(c.r, max(c.g, c.b));
      float s = clamp(l - threshold + knee, 0.0, 2.0 * knee); s = s * s / (4.0 * knee + 1e-4);
      gl_FragColor = vec4(c * (max(s, l - threshold) / max(l, 1e-4)), 1.0); }`,
    { tDiffuse: { value: null }, threshold: { value: 0.6 }, knee: { value: 0.22 } });
  const blur = mat(`uniform sampler2D tDiffuse; uniform vec2 dir; varying vec2 vUv;
    void main(){ vec3 s = texture2D(tDiffuse, vUv).rgb * 0.2270270270;
      s += texture2D(tDiffuse, vUv + dir * 1.3846153846).rgb * 0.3162162162; s += texture2D(tDiffuse, vUv - dir * 1.3846153846).rgb * 0.3162162162;
      s += texture2D(tDiffuse, vUv + dir * 3.2307692308).rgb * 0.0702702703; s += texture2D(tDiffuse, vUv - dir * 3.2307692308).rgb * 0.0702702703;
      gl_FragColor = vec4(s, 1.0); }`, { tDiffuse: { value: null }, dir: { value: new THREE.Vector2() } });
  const comp = mat(`uniform sampler2D tScene, tB1, tB2, tB3; uniform float w3, bsat; uniform float strength, w1, w2, vignette, aberr, radial, flash, sat, contrast, warm;
    varying vec2 vUv;
    void main(){
      vec2 uv = vUv, dc = uv - 0.5;
      vec3 c;
      if (radial > 0.002) {
        vec3 acc = vec3(0.0);
        for (int i = 0; i < 6; i++) { float t = float(i) / 5.0; acc += texture2D(tScene, uv - dc * radial * t * 0.055).rgb; }
        c = acc / 6.0;
      } else c = texture2D(tScene, uv).rgb;
      if (aberr > 0.002) { c.r = mix(c.r, texture2D(tScene, uv + dc * aberr * 0.014).r, 0.85); c.b = mix(c.b, texture2D(tScene, uv - dc * aberr * 0.014).b, 0.85); }
      vec3 bl = texture2D(tB1, uv).rgb * w1 + texture2D(tB2, uv).rgb * w2 + texture2D(tB3, uv).rgb * w3;
      bl = max(mix(vec3(dot(bl, vec3(0.299, 0.587, 0.114))), bl, bsat), 0.0);
      c += bl * strength;
      float l = dot(c, vec3(0.299, 0.587, 0.114));
      c = mix(vec3(l), c, sat);
      c = (c - 0.5) * contrast + 0.5;
      c *= vec3(1.0 + warm * 0.06, 1.0, 1.0 - warm * 0.04);
      c += flash * vec3(0.7, 0.78, 1.0);
      float v = smoothstep(0.92, 0.28, length(dc * vec2(1.0, 0.85)));
      c *= mix(1.0, v, vignette);
      c += (fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453) - 0.5) / 255.0; /* dithering: sin bandas */
      gl_FragColor = vec4(c, 1.0);
    }`, {
    tScene: { value: null }, tB1: { value: null }, tB2: { value: null }, tB3: { value: null }, w3: { value: 0 }, bsat: { value: 1.25 }, strength: { value: 0.9 }, w1: { value: 1 }, w2: { value: 1.2 },
    vignette: { value: 0.55 }, aberr: { value: 0 }, radial: { value: 0 }, flash: { value: 0 }, sat: { value: 1.1 }, contrast: { value: 1.05 }, warm: { value: 0 },
  });
  const qScene = new THREE.Scene(), qCam = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
  const quad = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), comp); quad.frustumCulled = false; qScene.add(quad);
  const opts = { minFilter: THREE.LinearFilter, magFilter: THREE.LinearFilter, format: THREE.RGBAFormat, depthBuffer: false, stencilBuffer: false };
  let main = null, A1, B1, A2, B2, A3, B3, W = 0, H = 0;
  const P = { enabled: true, level: 2, u: comp.uniforms, b: bright.uniforms };
  function make() {
    [main, A1, B1, A2, B2, A3, B3].forEach(t => t && t.dispose());
    main = new THREE.WebGLRenderTarget(W, H, { minFilter: THREE.LinearFilter, magFilter: THREE.LinearFilter, format: THREE.RGBAFormat, samples: P.level >= 2 ? 4 : 0 });
    main.isXRRenderTarget = true; /* r187: tone mapping + sRGB en el shader, como en r128 */
    main.texture.colorSpace = THREE.SRGBColorSpace; main.texture.internalFormat = 'RGBA8';
    const hw = Math.max(1, W >> 1), hh = Math.max(1, H >> 1), qw = Math.max(1, W >> 2), qh = Math.max(1, H >> 2);
    A1 = new THREE.WebGLRenderTarget(hw, hh, opts); B1 = new THREE.WebGLRenderTarget(hw, hh, opts);
    A2 = new THREE.WebGLRenderTarget(qw, qh, opts); B2 = new THREE.WebGLRenderTarget(qw, qh, opts);
    const ew = Math.max(1, W >> 3), eh = Math.max(1, H >> 3);
    A3 = new THREE.WebGLRenderTarget(ew, eh, opts); B3 = new THREE.WebGLRenderTarget(ew, eh, opts);
  }
  function pass(m, target) { quad.material = m; renderer.setRenderTarget(target); renderer.render(qScene, qCam); }
  function blurPass(src, dst, dx, dy) { blur.uniforms.tDiffuse.value = src.texture; blur.uniforms.dir.value.set(dx / src.width, dy / src.height); pass(blur, dst); }
  P.setSize = () => {
    const pr = renderer.getPixelRatio();
    const w = Math.max(1, Math.floor(innerWidth * pr)), h = Math.max(1, Math.floor(innerHeight * pr));
    if (w === W && h === H && main) return;
    W = w; H = h; if (P.enabled) make();
  };
  P.setLevel = lv => {
    P.level = lv; P.enabled = lv >= 1;
    if (P.enabled) { W = H = 0; P.setSize(); }
    document.body.classList.toggle('nopost', !P.enabled);
  };
  P.render = () => {
    if (!P.enabled) { renderer.setRenderTarget(null); renderer.render(scene, camera); return; }
    renderer.setRenderTarget(main); renderer.render(scene, camera);
    if (P.level >= 2) {
      bright.uniforms.tDiffuse.value = main.texture; pass(bright, A1);
      blurPass(A1, B1, 1, 0); blurPass(B1, A1, 0, 1);
      blurPass(A1, A2, 1.5, 0); blurPass(A2, B2, 0, 1.5); blurPass(B2, A2, 2, 0); blurPass(A2, B2, 0, 2);
      blurPass(B2, A3, 1, 0); blurPass(A3, B3, 0, 1); blurPass(B3, A3, 2, 0); blurPass(A3, B3, 0, 2);
      comp.uniforms.tB1.value = A1.texture; comp.uniforms.tB2.value = B2.texture; comp.uniforms.tB3.value = B3.texture;
      comp.uniforms.w1.value = 1; comp.uniforms.w2.value = 1.2; comp.uniforms.w3.value = 1.1;
    } else {
      bright.uniforms.tDiffuse.value = main.texture; pass(bright, A2);
      blurPass(A2, B2, 1, 0); blurPass(B2, A2, 0, 1); blurPass(A2, B2, 2, 0); blurPass(B2, A2, 0, 2);
      comp.uniforms.tB1.value = A2.texture; comp.uniforms.tB2.value = A2.texture; comp.uniforms.tB3.value = A2.texture;
      comp.uniforms.w1.value = 0.9; comp.uniforms.w2.value = 0.9; comp.uniforms.w3.value = 0;
    }
    comp.uniforms.tScene.value = main.texture;
    pass(comp, null);
  };
  return P;
})();

/* Adaptive quality: 3 = sharp + full bloom + shadows, 2 = full bloom, 1 = light bloom, 0 = no post */
const Quality = {
  level: IS_TOUCH ? 2 : 3, frames: 0, time: 0, settle: 2.5, locked: false, fastWindows: 0, ceiling: IS_TOUCH ? 2 : 3,
  apply() {
    const lv = this.level;
    renderer.setPixelRatio(Math.min(devicePixelRatio, lv >= 3 ? 2 : lv >= 2 ? 1.5 : lv >= 1 ? 1.25 : 1));
    renderer.setSize(innerWidth, innerHeight);
    const shadows = lv >= 3;
    if (renderer.shadowMap.enabled !== shadows) { renderer.shadowMap.enabled = shadows; sun.castShadow = shadows; allMaterials.forEach(m => { m.needsUpdate = true; }); }
    Post.setLevel(lv >= 2 ? 2 : lv >= 1 ? 1 : 0);
  },
  // Measures real frame time and steps quality down if the device struggles
  sample(dt) {
    if (this.locked) return;
    this.settle -= dt; if (this.settle > 0) return;
    this.frames++; this.time += dt;
    if (this.time >= 2) {
      const fps = this.frames / this.time; this.frames = 0; this.time = 0;
      if (fps < 45 && this.level > 0) {
        this.level--; this.apply(); this.settle = 3; this.fastWindows = 0;
      } else if (fps > 58 && this.level < this.ceiling) {
        if (++this.fastWindows >= 5) { this.level++; this.apply(); this.settle = 6; this.fastWindows = 0; }
      } else this.fastWindows = 0;
    }
  },
};

/* =====================================================================
   WEATHER: rain, wet road with light reflections, lightning
   ===================================================================== */
const Weather = { rain: 0, wet: 0, flash: 0, bolt: 6, target: 0 };
const RAIN_N = IS_TOUCH ? 450 : 900;
const rainPos = new Float32Array(RAIN_N * 6);
const rainGeo = new THREE.BufferGeometry();
rainGeo.setAttribute('position', new THREE.BufferAttribute(rainPos, 3).setUsage(THREE.DynamicDrawUsage));
const rainMat = track(bent(new THREE.LineBasicMaterial({ color: 0xb8d2ff, transparent: true, opacity: 0, depthWrite: false, toneMapped: false })));
const rainLines = new THREE.LineSegments(rainGeo, rainMat);
rainLines.frustumCulled = false; rainLines.renderOrder = 6; scene.add(rainLines);
const DROPS = [];
for (let i = 0; i < RAIN_N; i++) DROPS.push({ x: rand(-24, 24), y: rand(0, 28), z: rand(-75, 12), v: rand(30, 42) });

// Light reflections stretched along the wet asphalt (one draw call)
const streakTex = canvasTex(64, 256, (x, w, h) => {
  const g = x.createRadialGradient(w / 2, h * 0.5, 0, w / 2, h * 0.5, w / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)'); g.addColorStop(0.45, 'rgba(255,255,255,.35)'); g.addColorStop(1, 'rgba(255,255,255,0)');
  x.setTransform(1, 0, 0, h / w, 0, 0); x.fillStyle = g; x.fillRect(0, 0, w, w);
}, false);
const reflMat = track(bent(new THREE.MeshBasicMaterial({ map: streakTex, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -4, polygonOffsetUnits: -8, toneMapped: false })));
const REFL_CAP = 160;
const reflMesh = inst(new THREE.PlaneGeometry(1, 1).rotateX(-Math.PI / 2), reflMat, REFL_CAP);
for (let i = 0; i < REFL_CAP; i++) reflMesh.setColorAt(i, new THREE.Color(1, 1, 1));
reflMesh.renderOrder = 3; reflMesh.count = 0;
const _rc = new THREE.Color();
const Refl = {
  n: 0,
  begin() { this.n = 0; },
  add(x, z, w, len, r, g, b, a) {
    if (this.n >= REFL_CAP || a < 0.01 || z > 14 || z < -170) return;
    const i = this.n++;
    setInst(reflMesh, i, x, 0.035, z + len * 0.45, w, 1, len);
    reflMesh.setColorAt(i, _rc.setRGB(r * a, g * a, b * a));
  },
  end() { reflMesh.count = this.n; reflMesh.instanceMatrix.needsUpdate = true; if (reflMesh.instanceColor) reflMesh.instanceColor.needsUpdate = true; },
};

function updateWeather(dt, ws, target, tunnel) {
  Weather.target = target;
  Weather.rain = damp(Weather.rain, Weather.target, 0.8, dt);
  Weather.wet = damp(Weather.wet, Weather.rain > 0.15 ? 1 : 0, 0.35, dt);
  const vis = Weather.rain * (1 - tunnel);
  rainMat.opacity = 0.42 * vis;
  rainLines.visible = vis > 0.01;
  if (rainLines.visible) {
    const cx = camera.position.x, slant = 0.035 * ws;
    for (let i = 0; i < RAIN_N; i++) {
      const p = DROPS[i];
      p.y -= p.v * dt; p.z += ws * dt;
      if (p.y < 0 || p.z > 14) {
        if (p.y < 0 && p.z > -40 && Math.random() < 0.3) glow.add(p.x, 0.1, p.z, 0.5, 0.7, 0.8, 1, 0.5 * vis);
        p.y = rand(16, 28); p.z = rand(-75, 6); p.x = cx + rand(-24, 24);
      }
      const k = i * 6;
      rainPos[k] = p.x; rainPos[k + 1] = p.y; rainPos[k + 2] = p.z;
      rainPos[k + 3] = p.x; rainPos[k + 4] = p.y + 1.3; rainPos[k + 5] = p.z - slant;
    }
    rainGeo.attributes.position.needsUpdate = true;
  }
  // Lightning during the storm
  Weather.flash *= Math.exp(-dt * 7);
  if (Weather.rain > 0.6 && tunnel < 0.5) {
    Weather.bolt -= dt;
    if (Weather.bolt <= 0) {
      Weather.bolt = rand(4, 9); Weather.flash = 1;
      setTimeout(() => { Weather.flash = Math.max(Weather.flash, 0.7); }, 120);
      const dly = rand(0.4, 1.4);
      AudioSys.thunder(dly);
    }
  }
  // Wet asphalt: glossier, darker, reflects the sky
  road.material.roughness = lerp(lerp(0.85, 0.5, todState.night), 0.2, Weather.wet);
  road.material.envMapIntensity = Weather.wet * 0.9;
  road.material.color.setScalar(lerp(1, 0.72, Weather.wet));
  reflMat.opacity = Weather.wet * 0.85;
  scene.fog.near = lerp(70, 35, Weather.rain); scene.fog.far = lerp(360, 230, Weather.rain);
  skyMat.uniforms.flash.value = Weather.flash;
  skyMat.uniforms.storm.value = Weather.rain;
  AudioSys.rain(vis);
}

/* =====================================================================
   ZONES: tunnels, arch bridges over a river, roadworks
   Placed by distance with a fixed seed (same layout for everyone).
   ===================================================================== */
let worldDist = 0;
const Zones = { list: [], tunnel: 0 };
const zz = dist => -(dist - worldDist);
const ZONE_LEN = { tunnel: [240, 300], bridge: [260, 320], works: [150, 170] };

ZONE_HIDE = (z, kind, half) => {
  for (const Z of Zones.list) {
    if (Z.type === 'works') continue;
    if (kind === 'lamp' && Z.type !== 'tunnel') continue;
    const pad = Z.type === 'bridge' ? 14 : 4;
    if (z < zz(Z.start) + half + pad && z > zz(Z.end) - half - pad) return true;
  }
  return false;
};

/* ---------- Shared meshes ---------- */
const concreteMat = std({ color: col(0x8f959e), roughness: 0.92 });
const darkConcreteMat = std({ color: col(0x5d636c), roughness: 0.95 });
const T_CAP = 100;
const tunnelTex = new THREE.TextureLoader().load(TEX.tunnel); tunnelTex.colorSpace = THREE.SRGBColorSpace; tunnelTex.anisotropy = 8;
const tunnelWallMat = std({ color: 0xffffff, map: tunnelTex, roughness: 0.85 });
const tWall = inst(new THREE.BoxGeometry(1.2, 8, 8.05), tunnelWallMat, T_CAP * 2);
const tCeil = inst(new THREE.BoxGeometry(22, 1, 8.05), darkConcreteMat, T_CAP);
const tFloor = inst(new THREE.BoxGeometry(20.6, 0.1, 8.05), darkConcreteMat, T_CAP);
const tLightMat = basic({ color: new THREE.Color(1.3, 0.95, 0.6) });
