  Z.cones = [];
  for (let off = 0; off <= 30; off += 3) Z.cones.push({ off, x: lerp(x0, lineX, off / 30), alive: true });
  for (let off = 34; off <= Z.len; off += 6) Z.cones.push({ off, x: lineX, alive: true });
