    AudioSys.sfx('shield'); flash(COL.cyan); buzz(60);
    burst(o.x, 1, z, 34, { color: [0.2, 0.76, 0.94], speed: 12, up: 8, life: 0.7, size: 0.8, spread: 1, grav: 8 });
