Object.values(TOD).forEach(p => ['top', 'hor', 'bot', 'sun', 'hs', 'hg'].forEach(k => { p[k] = col(p[k]); }));
const KEYS = [[0, 'dawn'], [0.09, 'day'], [0.47, 'day'], [0.55, 'dusk'], [0.63, 'night'], [0.91, 'night'], [1, 'dawn']];
