  C('sun', skyMat.uniforms.sunCol.value);
  scene.fog.color.copy(skyMat.uniforms.horizon.value);
  // Painted panoramas: weight per time of day, and fog matched to their horizon haze
  const PI = { dawn: 0, day: 1, dusk: 2, night: 3 }, pwv = [0, 0, 0, 0];
  pwv[PI[a[1]]] += 1 - t; pwv[PI[b[1]]] += t;
