    _c.setRGB(0, 0, 0); pwv.forEach((w, i) => { _c.r += PANO_HAZE[i].r * w; _c.g += PANO_HAZE[i].g * w; _c.b += PANO_HAZE[i].b * w; });
    scene.fog.color.lerp(_c, 0.85);
