  if (dayArc) { skyMat.uniforms.sunDir.value.copy(dir); skyMat.uniforms.moonDir.value.set(0, -1, 0); }
  else { skyMat.uniforms.moonDir.value.copy(dir); skyMat.uniforms.sunDir.value.set(0, -1, 0); }
  skyMat.uniforms.night.value = night;
  sun.color.copy(skyMat.uniforms.sunCol.value);
  sun.intensity = L('sunI') * LK * (0.15 + 0.85 * smooth(0, 0.3, el));
  const ld = dir.clone(); ld.y = Math.max(ld.y, 0.45); ld.normalize();
  sun.position.set(player.x + ld.x * 60, ld.y * 60, ld.z * 60 - 6);
  sun.target.position.set(player.x, 0, -6);
