    if (fxChance(0.5, dt)) emit({ x: player.x + rand(-0.5, 0.5), y: 1, z: rand(-1, 1), vx: rand(-0.5, 0.5), vy: rand(1.5, 3), vz: 0, life: 2.2, max: 2.2, size: 1.5, grow: 2.2, r: 0.16, g: 0.16, b: 0.18, add: false, grav: 0, drag: 0.6, world: true });
