/* ---------- Friend challenges: portable, unverified score targets ---------- */
const CHALLENGE_PREFIX = 'NS6-';
function cleanNickname(value) {
  return String(value || '').normalize('NFKC').replace(/[<>\x00-\x1f\x7f]/g, '').trim().slice(0, 20) || 'RACER';
}
function validateChallenge(value) {
  if (!value || value.v !== 1 || !CARS.some(c => c.id === value.car)) throw new Error('Invalid challenge');
  const ints = ['score', 'dist', 'combo'];
  if (ints.some(k => !Number.isSafeInteger(value[k]) || value[k] < 0) || value.score < 1 || value.score > 100000000 || value.dist > 10000000 || value.combo > 100000) throw new Error('Invalid score');
  const upgrades = {};
  for (const k of ['engine','handling','nitro','magnet']) {
    const n = value.upgrades && value.upgrades[k];
    if (!Number.isInteger(n) || n < 0 || n > 5) throw new Error('Invalid setup');
    upgrades[k] = n;
  }
  return {v:1, name:cleanNickname(value.name), score:value.score, dist:value.dist, combo:value.combo, car:value.car, upgrades, tune:sanitizeTune(value.tune)};
}
function encodeChallenge(value) {
  const bytes = new TextEncoder().encode(JSON.stringify(validateChallenge(value)));
  return CHALLENGE_PREFIX + btoa(Array.from(bytes, b => String.fromCharCode(b)).join('')).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
}
function decodeChallenge(text) {
  let raw = String(text || '').trim();
  if (raw.length > 4096) throw new Error('Challenge too long');
  if (/^https?:\/\//i.test(raw)) raw = new URLSearchParams(new URL(raw).hash.slice(1)).get('challenge') || '';
  if (!raw.startsWith(CHALLENGE_PREFIX)) throw new Error('Use a Neon Speed v6 link or code');
  const encoded = raw.slice(CHALLENGE_PREFIX.length);
  if (!/^[A-Za-z0-9_-]+$/.test(encoded)) throw new Error('Invalid code');
  const bytes = Uint8Array.from(atob(encoded.replace(/-/g,'+').replace(/_/g,'/')), ch => ch.charCodeAt(0));
  return validateChallenge(JSON.parse(new TextDecoder('utf-8', {fatal:true}).decode(bytes)));
}
function challengeAddress(result, href = location.href) {
  const code = encodeChallenge(result), url = new URL(href);
  if (url.protocol !== 'http:' && url.protocol !== 'https:') return {text:code, isLink:false};
  // Do not include unrelated query parameters or an old challenge in a shared URL.
  url.search = ''; url.hash = new URLSearchParams({challenge:code}).toString();
  return {text:url.href, isLink:true};
}
let activeChallenge = null, lastResult = null, coachDismissed = false;
function saveNickname() {
  save.nickname = cleanNickname($('racer-name').value); $('racer-name').value = save.nickname; persist();
  document.querySelectorAll('.pname').forEach(el => { el.textContent = save.nickname; });
}
function openFriends() {
  renderBetList(); betSync(true);
  $('racer-name').value = cleanNickname(save.nickname);
  $('friend-error').textContent = '';
  const history = $('friend-history'); history.replaceChildren();
  const list = Array.isArray(save.challengeHistory) ? save.challengeHistory.slice(0,6) : [];
  for (const entry of list) {
    const row = document.createElement('div'); row.className = 'friend-history-row';
    row.textContent = `${entry.won ? '✓' : '↗'} ${cleanNickname(entry.name)} · ${fmt(Number(entry.score) || 0)} / ${fmt(Number(entry.target) || 0)} pts`;
    history.appendChild(row);
  }
  if (!list.length) history.textContent = 'Your completed challenges will appear here on this device.';
  frLoad(); $('friends-dialog').showModal();
}
function previewChallenge() {
  try {
    const target = decodeChallenge($('friend-code').value);
    $('friend-preview').textContent = `${target.name} · beat ${fmt(target.score)} points · ${carById(target.car).name}. Their car and upgrades are provided for this run. Traffic varies each run.`;
    $('friend-start').disabled = false;
    $('friend-error').textContent = '';
    return target;
  } catch (err) {
    $('friend-preview').textContent = ''; $('friend-start').disabled = true;
    $('friend-error').textContent = 'That link or code is not valid. Paste the complete Neon Speed v6 challenge.';
    return null;
  }
}
function acceptChallenge() {
  const target = previewChallenge(); if (!target) return;
  saveNickname(); activeChallenge = target; $('friends-dialog').close(); startRun();
}
function nextUnlockText() {
  const next = CARS.find(c => !save.owned.includes(c.id));
  if (!next) return 'Your garage is complete. Chase a new combo record!';
  const left = Math.max(0, next.price - save.coins);
  return left ? `${fmt(left)} coins to ${next.name}` : `${next.name} is ready to unlock in the garage`;
}
function claimResultRewards() {
  ensureMissions(); let reward = 0;
  save.missions.list.forEach(m => {
    if (!m.claimed && m.progress >= missionGoal(m)) { m.claimed = true; reward += missionReward(m); }
  });
  if (reward) { save.coins += reward; persist(); AudioSys.sfx('mission'); }
  $('go-claim').hidden = true;
  $('go-missions').textContent = reward ? `+${fmt(reward)} mission coins added to your wallet` : 'All completed rewards have been claimed.';
  $('go-next').textContent = nextUnlockText();
}
function updateRunExperience() {
  if (state !== 'playing') { $('drive-coach').hidden = true; return; }
  const target = run.challenge ? run.challenge.score : run.recordBefore;
  const targetName = run.challenge ? run.challenge.name : 'PERSONAL BEST';
  setText('goal-label', target > 0 ? targetName : 'FIRST MILESTONE');
  const goal = target > 0 ? target + 1 : 1000;
  const remaining = Math.max(0, goal - Math.floor(run.score));
  setText('goal-value', remaining ? `${fmt(remaining)} pts to go` : (run.challenge ? 'CHALLENGE BEATEN!' : 'TARGET REACHED!'));
  setStyle('goal-fill','width', Math.min(100,run.score / goal * 100).toFixed(1)+'%');
  if (!remaining && !run.goalCelebrated) {
    run.goalCelebrated = true; toast(run.challenge ? 'CHALLENGE BEATEN!' : 'TARGET REACHED!', 'Keep going — every point counts', '#3dff8a');
  }
  if (input.left || input.right) run.didSteer = true;
  const coach = $('drive-coach');
  coach.hidden = !!save.tutorialDone || coachDismissed || run.time > 45;
  if (!coach.hidden) {
    let message;
    if (!run.didSteer) message = IS_TOUCH ? 'Hold ◀ or ▶ to steer. Acceleration is automatic.' : 'Use ← → or A / D to steer. Acceleration is automatic.';
    else if (!run.nitroUses) message = IS_TOUCH ? 'Hold NITRO on a clear stretch to boost.' : 'Hold SHIFT or SPACE on a clear stretch to boost.';
    else if (!run.nearMisses) message = 'Pass close to traffic to refill nitro and build a combo.';
    else { save.tutorialDone = true; persist(); coach.hidden = true; }
    if (message) setText('coach-copy', message);
  }
}
function captureResult() {
  const setup = run.setup;
  lastResult = {v:1, name:cleanNickname(save.nickname), score:Math.floor(run.score), dist:Math.round(run.dist), combo:run.bestCombo, car:setup.car, upgrades:{...setup.upgrades}, tune:sanitizeTune(setup.tune)};
  $('go-share').disabled = lastResult.score < 1;
  const target = run.challenge;
  $('go-outcome').textContent = target ? (lastResult.score > target.score ? `You beat ${target.name} by ${fmt(lastResult.score - target.score)} points!` : `${fmt(target.score + 1 - lastResult.score)} more points to beat ${target.name}. Try again!`) : (run.recordBefore > lastResult.score ? `${fmt(run.recordBefore + 1 - lastResult.score)} points from a new personal best` : 'Keep the streak going. Set a score your friends can chase.');
  $('go-next').textContent = nextUnlockText();
  $('go-claim').hidden = claimableCount() === 0;
  if (target) {
    const entry = {name:target.name, target:target.score, score:lastResult.score, won:lastResult.score > target.score};
    save.challengeHistory = [entry, ...(Array.isArray(save.challengeHistory) ? save.challengeHistory : [])].slice(0,12); persist();
  }
}
function drawResultCard(result) {
  const c = $('result-card'), x = c.getContext('2d'); c.width = 1080; c.height = 1350;
  const bg = x.createLinearGradient(0,0,1080,1350);bg.addColorStop(0,'#111435');bg.addColorStop(1,'#030610');x.fillStyle=bg;x.fillRect(0,0,1080,1350);
  x.strokeStyle='#17364b';x.lineWidth=2;
  for(let i=-900;i<1800;i+=100){x.beginPath();x.moveTo(540,680);x.lineTo(i,1350);x.stroke();}
  for(let y=820;y<1350;y+=70){x.beginPath();x.moveTo(0,y);x.lineTo(1080,y);x.stroke();}
  x.fillStyle='#00f0ff';x.fillRect(72,72,72,6);x.font='bold 28px sans-serif';x.fillText('THE CHASE IS ON',72,130);
  x.font='italic 900 88px sans-serif';x.fillStyle='#fff';x.fillText('NEON SPEED',66,250);
  x.font='bold 34px sans-serif';x.fillStyle='#b9c5df';x.fillText(result.name,72,330);
  x.fillStyle='#00f0ff';x.font='900 148px sans-serif';x.fillText(fmt(result.score),66,540,930);
  x.font='bold 28px sans-serif';x.fillStyle='#b9c5df';x.fillText('POINTS TO BEAT',72,595);
  x.fillStyle='#ffffff';x.font='bold 54px sans-serif';x.fillText((result.dist/1000).toFixed(2)+' KM',72,760);x.fillText('×'+result.combo,620,760);
  x.font='24px sans-serif';x.fillStyle='#9baac8';x.fillText('DISTANCE',72,805);x.fillText('BEST COMBO',620,805);
  x.fillStyle='#ff2bd6';x.fillRect(72,890,936,3);x.fillStyle='#fff';x.font='bold 34px sans-serif';x.fillText(carById(result.car).name,72,965);
  x.font='25px sans-serif';x.fillStyle='#b9c5df';x.fillText('Same car. Same upgrades. Your turn.',72,1018);
  x.font='bold 48px sans-serif';x.fillStyle='#00f0ff';x.fillText('CAN YOU BEAT ME?',72,1160);
  x.font='23px sans-serif';x.fillStyle='#9baac8';x.fillText('Open the challenge link or paste its code in FRIENDS.',72,1230);
  return c;
}
function openResultShare() {
  if (!lastResult || lastResult.score < 1) return;
  const address = challengeAddress(lastResult);
  $('share-code').value = address.text;
  $('share-help').textContent = address.isLink ? 'Send this link with your card. Your friend opens it and accepts the challenge.' : 'You are playing a local file. Send this code to a friend with Neon Speed v6; they can paste it in FRIENDS. The card alone does not contain the challenge.';
  $('copy-challenge').textContent = address.isLink ? 'COPY LINK' : 'COPY CODE';
  $('share-status').textContent=''; drawResultCard(lastResult); $('share-dialog').showModal();
}
async function copyChallenge() {
  const field=$('share-code');
  try { await navigator.clipboard.writeText(field.value); $('share-status').textContent='Copied. Ready to send to a friend.'; }
  catch { field.focus();field.select();$('share-status').textContent='Select and copy the highlighted text with your device’s Copy action.'; }
}
async function shareChallenge() {
  if (!lastResult) return;
  const address=challengeAddress(lastResult), message=`${lastResult.name} challenges you to beat ${fmt(lastResult.score)} points in Neon Speed!`;
  if (!navigator.share) { await copyChallenge(); return; }
  try {
    const data={title:'Neon Speed · Beat my score',text:message+(address.isLink?'':'\n'+address.text)};
    if(address.isLink)data.url=address.text;
    await navigator.share(data);$('share-status').textContent='Sharing completed.';
  } catch(err) { if(err.name!=='AbortError') await copyChallenge(); }
}
function downloadResultCard() {
  drawResultCard(lastResult).toBlob(blob=>{
    if(!blob){$('share-status').textContent='Could not create the card. Try again.';return;}
    const url=URL.createObjectURL(blob), a=document.createElement('a');a.href=url;a.download='Neon-Speed-'+lastResult.score+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);
    $('share-status').textContent='Card downloaded. Include the challenge link or code when sending it.';
  },'image/png');
}

