    const a = race.stZ - FUEL.PIT_OUT - 6, b = race.stZ + FUEL.PIT_IN + 6; let ch = false;
    POSTS.forEach((p, i) => { if (p.s > 0 && p.z > a && p.z < b) { setInst(postMesh, i, 9.15, 0, p.z, HIDE, HIDE, HIDE); ch = true; } });
