/* ---------- Vallas publicitarias: anuncios propios, al azar ---------- */
// Los anuncios extra son archivos aparte (img/ads/*.webp) que se cargan después del arranque.
// Cada valla elige anuncio al azar cada vez que reaparece por delante.
const Ads = (() => {
  const A = { extra: [] };
  const LIST = [['tiburon', [0.45, 0.85, 1]], ['titanic', [0.6, 0.8, 1]], ['despertador', [1, 0.6, 0.2]], ['agua', [0.5, 0.75, 1]]];
  const BASE = SIGNS.length, W = 1024 / 372 / (8 / 3.5); // estas vallas son más anchas que las del juego
  LIST.forEach(a => SIGNS.push({ glow: a[1] }));
  SIGN_OBJS.forEach(o => {
    o.panel = o.g.children[0]; o.base = o.si;
    o.mat = basic({ map: signMats[o.si].map });
    o.panel.material = o.panel.material.slice(); o.panel.material[4] = o.mat;
    o.pz = o.g.position.z;
  });
  const assign = o => {
    const ex = A.extra.length && Math.random() < 0.5 ? pick(A.extra) : null;
    if (ex) { o.mat.map = ex.tex; o.si = BASE + ex.k; o.panel.scale.x = W; }
    else { const k = Math.floor(Math.random() * signMats.length); o.mat.map = signMats[k].map; o.si = k % BASE; o.panel.scale.x = 1; }
    o.mat.needsUpdate = true;
  };
  A.refresh = () => SIGN_OBJS.forEach(assign);
  A.scroll = () => SIGN_OBJS.forEach(o => {
    const z = o.g.position.z;
    if (z < o.pz - 100) assign(o); // ha dado la vuelta: anuncio nuevo
    o.pz = z; o.mat.color.copy(signMats[0].color);
  });
  A.load = () => {
    const L = new THREE.TextureLoader();
    LIST.forEach((a, k) => L.load('img/ads/' + a[0] + '.webp?v=' + (window.NS_BUILD || '1'), tex => {
      tex.colorSpace = THREE.SRGBColorSpace; tex.anisotropy = 8;
      A.extra.push({ tex, k });
    }));
  };
  setTimeout(A.load, 2500);
  return A;
})();
{
  const _sw = scrollWorld;
  scrollWorld = function (d, t) { _sw(d, t); Ads.scroll(); };
  const _aw = applyWorldNow;
  applyWorldNow = (id, pack) => { _aw(id, pack); Ads.refresh(); };
}

/* =====================================================================
   CURVAS Y DERRAPE (modo libre)
   - Curvas medias y cerradas, con aviso en pantalla
   - Derrape: girar hacia dentro de la curva a buena velocidad cruza el coche; cuanto más dura, más puntos.
     Al terminar se cobran los puntos y recarga nitro. Tocar el muro pierde lo acumulado.
   - Menos tráfico dentro de las curvas fuertes
   ===================================================================== */
const Drift = (() => {
  const D = { a: 0, pts: 0, t: 0, kind: 0, yaw: 0, sfxT: 0, best: 0 };
  const ok = () => state === 'playing' && !race.active && !run.daily && !run.challenge;
  let lastTight = false;

  // Aviso de curva
  const warn = document.createElement('div');
  warn.id = 'curvewarn';
  warn.style.cssText = 'position:fixed;left:50%;top:22%;transform:translateX(-50%);z-index:30;pointer-events:none;opacity:0;transition:opacity .25s;' +
    "font-family:'Orbitron',sans-serif;font-weight:900;letter-spacing:.14em;text-align:center;text-shadow:0 0 14px currentColor";
  const live = document.createElement('div');
  live.id = 'driftlive';
  live.style.cssText = 'position:fixed;left:50%;top:31%;transform:translateX(-50%);z-index:30;pointer-events:none;opacity:0;transition:opacity .15s;' +
    "font-family:'Orbitron',sans-serif;font-weight:900;font-size:clamp(18px,4.2vw,30px);letter-spacing:.1em;color:#ffd23f;text-shadow:0 0 16px #ff7a3c";
  document.body.appendChild(warn); document.body.appendChild(live);
  let warnT = 0;
  const announce = (s, k) => {
    const arrows = s > 0 ? '›››' : '‹‹‹';
    warn.style.color = k === 2 ? '#ff3b5c' : '#ffd23f';
    warn.innerHTML = `<div style="font-size:clamp(30px,8vw,58px);line-height:1">${arrows}</div><div style="font-size:clamp(12px,3vw,18px)">${k === 2 ? 'SHARP ' : ''}${s > 0 ? 'RIGHT' : 'LEFT'}</div>`;
    warn.style.opacity = 1; warnT = 2.4;
  };

  // Siguiente tramo: devuelve la curvatura objetivo
  D.next = () => {
    D.kind = 0;
    const gentle = () => (Math.random() < 0.3 ? 0 : rand(-1, 1) * 0.0011);
    if (!ok() || (run.dist || 0) < 500) return gentle();
    if (Zones.list.some(z => z.type === 'bridge' || z.type === 'tunnel')) return gentle(); // en puentes y túneles la estructura se deformaría
    const r = Math.random(), s = Math.random() < 0.5 ? -1 : 1;
    if (lastTight) { lastTight = false; return Math.random() < 0.6 ? 0 : rand(-1, 1) * 0.0008; } // respiro tras una cerrada
    if (r < 0.2) return 0;
    if (r < 0.5) return rand(-1, 1) * 0.0011;
    if (r < 0.82) { D.kind = 1; bend.dist = rand(330, 470); announce(s, 1); return s * rand(0.0017, 0.0022); }
    D.kind = 2; lastTight = true; bend.dist = rand(300, 400); announce(s, 2); return s * rand(0.0026, 0.0031);
  };
  // Empuje lateral de la curva: nunca más de lo que el coche puede compensar girando
  D.cf = (cf, latMax) => {
    if (!ok()) return cf;
    const lim = latMax * 0.6;
    const c = clamp(cf, -lim, lim);
    // Derrapando, el coche desliza hacia fuera casi tanto como gira hacia dentro: se puede mantener el derrape toda la curva
    return Math.sign(c) * lerp(Math.abs(c), latMax * 0.86, D.a * D.a);
  };
  // Separación entre grupos de tráfico (más aire en curvas fuertes)
  D.gap = () => (ok() ? (D.kind === 2 ? 2 : D.kind === 1 ? 1.5 : 1) : 1);

  const bank = () => {
    const pts = Math.round(D.pts / 10) * 10;
    D.pts = 0; D.t = 0; live.style.opacity = 0;
    if (pts < 50) return;
    addScore(pts);
    player.nitro = Math.min(100, player.nitro + Math.min(35, pts / 30));
    run.combo++; run.comboTimer = 3.2; run.bestCombo = Math.max(run.bestCombo, run.combo);
    D.best = Math.max(D.best, pts);
    toast(pts >= 1000 ? 'MEGA DRIFT' : pts >= 500 ? 'GREAT DRIFT' : 'DRIFT', '+' + pts * (player.x2 > 0 ? 2 : 1), pts >= 500 ? '#ff2bd6' : '#ffd23f');
    AudioSys.sfx('near', Math.min(6, 1 + (pts / 200 | 0)));
  };
  D.update = dt => {
    if (warnT > 0 && (warnT -= dt) <= 0) warn.style.opacity = 0;
    if (state !== 'playing') { if (D.pts || D.a) { D.pts = 0; D.a = 0; D.t = 0; live.style.opacity = 0; warn.style.opacity = 0; } return; }
    const cur = Math.abs(bend.x), dir = Math.sign(bend.x), sf = player.speed / P.maxSpeed;
    if (player.wall && D.pts > 60) { D.pts = 0; D.t = 0; live.style.opacity = 0; toast('DRIFT LOST', 'Hit the wall', '#ff3b5c'); }
    const can = ok() && cur > 0.0012 && sf > 0.5 && !player.wall;
    const want = can && player.steer * dir > 0.3;
    const was = D.a;
    D.a = damp(D.a, want ? 1 : 0, want ? 5 : 3.5, dt);
    if (D.a > 0.3 && can) {
      D.t += dt;
      D.pts += (cur / 0.003) * sf * 110 * (1 + D.t * 0.15) * dt;
      player.speed *= 1 - 0.025 * D.a * dt;
      if (was <= 0.3 || (D.sfxT -= dt) <= 0) { AudioSys.sfx('screech'); D.sfxT = 0.85; }
      if (fxChance(0.95, dt)) for (const s of [-0.85, 0.85])
        emit({ x: player.x + s, y: 0.2, z: 1.7, vx: -dir * rand(1, 3), vy: rand(0.5, 1.4), vz: rand(2, 5), life: 0.8, max: 0.8, size: 1.2, grow: 2.6, r: 0.85, g: 0.85, b: 0.9, add: false, grav: 0, drag: 1.2 });
      if (D.pts > 30) { live.textContent = 'DRIFT ' + (Math.round(D.pts / 10) * 10); live.style.opacity = 1; }
    } else if (D.pts > 0 && D.a < 0.2) bank();
    // el coche se cruza: morro hacia dentro de la curva
    D.yaw = damp(D.yaw, -dir * 0.42 * D.a, 7, dt);
  };
  return D;
})();
{
  const _up = updatePlayer;
  updatePlayer = function (dt) { _up(dt); Drift.update(dt); };
  const _uv = updatePlayerVisual;
  updatePlayerVisual = function (dt, ws) { _uv(dt, ws); if (Drift.yaw) playerModel.root.rotation.y += Drift.yaw; };
}
window.__nsPolish.Drift = Drift; window.__nsPolish.bend = bend;

/* =====================================================================
   AGUA: un solo shader para el río de los puentes, el mar de Miami y los charcos
   Oleaje procedural animado, reflejo del cielo con Fresnel físico, destellos, color por cresta y espuma.
   Sin texturas.
   ===================================================================== */
const Water = (() => {
  const T = { value: 0 }, list = [];
  // o: scale (tamaño del oleaje), amp, deep/crest [día, noche], off (uniform de desplazamiento), shore (x local de la orilla), hole
  function apply(m, o) {
    const U = { uWT: T, uWDeep: { value: new THREE.Color() }, uWCrest: { value: new THREE.Color() },
      uWP: { value: new THREE.Vector4(o.scale || 1, o.amp || 1, o.shore == null ? 1e6 : o.shore, o.foam == null ? 1 : o.foam) }, uWOff: o.off || { value: new THREE.Vector2() } };
    if (o.hole) U.uHole = holeUniform;
    m.map = null; m.metalness = 0; m.roughness = o.rough || 0.1; m.envMapIntensity = o.env || 1.15; m.color.set(0xffffff);
    if (m.emissive) m.emissive.set(0);
    const prev = m.onBeforeCompile;
    m.onBeforeCompile = (sh, r) => {
      prev(sh, r);
      Object.assign(sh.uniforms, U);
      sh.vertexShader = 'varying vec2 vWxz; varying float vWz2;\n' + sh.vertexShader.replace('#include <begin_vertex>',
        '#include <begin_vertex>\n  vWxz = (mat3(modelMatrix) * position).xz; vWz2 = (modelMatrix * vec4(position, 1.0)).z;');
      sh.fragmentShader = `varying vec2 vWxz; varying float vWz2; uniform float uWT; uniform vec3 uWDeep, uWCrest; uniform vec4 uWP; uniform vec2 uWOff;
${o.hole ? 'uniform vec4 uHole;' : ''}
vec3 nsWv(vec2 p, vec2 d, float k, float sp, float a) { float ph = dot(p, d) * k + uWT * sp; return vec3(d * (k * a * cos(ph)), a * sin(ph)); }
float nsWh(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float nsWn(vec2 p) { vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(nsWh(i), nsWh(i + vec2(1.0, 0.0)), f.x), mix(nsWh(i + vec2(0.0, 1.0)), nsWh(i + vec2(1.0, 1.0)), f.x), f.y); }
vec3 nsWater = vec3(0.0);
` + sh.fragmentShader
        .replace('#include <color_fragment>', `#include <color_fragment>
  {
    ${o.hole ? 'if ((vWz2 < uHole.x && vWz2 > uHole.y) || (vWz2 < uHole.z && vWz2 > uHole.w)) discard;' : ''}
    vec2 P = (vWxz + uWOff) * uWP.x;
    float wd = length(vViewPosition), fine = clamp(60.0 / wd, 0.0, 1.0);
    vec3 w = nsWv(P, normalize(vec2(1.0, 0.35)), 0.22, 0.9, 0.42) + nsWv(P, normalize(vec2(-0.6, 1.0)), 0.41, 1.25, 0.2)
           + (nsWv(P, normalize(vec2(0.3, -1.0)), 1.3, 2.1, 0.06) + nsWv(P, normalize(vec2(-1.0, -0.2)), 2.9, 3.0, 0.025)) * fine;
    vec2 rp = P * 1.6 + vec2(uWT * 0.5, -uWT * 0.35); float e = 0.35;
    float n0 = nsWn(rp) + 0.5 * nsWn(rp * 2.3 + 11.0);
    vec2 rg = vec2(nsWn(rp + vec2(e, 0.0)) + 0.5 * nsWn((rp + vec2(e, 0.0)) * 2.3 + 11.0) - n0, nsWn(rp + vec2(0.0, e)) + 0.5 * nsWn((rp + vec2(0.0, e)) * 2.3 + 11.0) - n0) / e;
    w.xy += rg * 0.085 * fine;
    w.xy *= uWP.y;
    nsWater = w;
    float crest = smoothstep(0.1, 0.75, w.z);
    float foam = smoothstep(0.66, 0.95, w.z + (n0 - 0.75) * 0.5) * fine * uWP.w;
    // orilla: agua más clara y espuma que va y viene
    float sd = uWP.z - vWxz.x, lap = 3.0 + 2.2 * sin(uWT * 0.9 + vWxz.y * 0.11 + n0 * 2.0);
    float shore = step(sd, 900.0) * smoothstep(45.0, 0.0, sd);
    foam += step(sd, 900.0) * (smoothstep(lap + 1.6, lap, sd) * 0.9 + smoothstep(lap * 2.4 + 1.0, lap * 2.4, sd) * 0.35 * n0);
    diffuseColor.rgb = mix(mix(uWDeep, uWCrest, crest), uWCrest * 1.25, shore * 0.7) + foam * 0.3;
  }`)
        .replace('#include <normal_fragment_maps>', `#include <normal_fragment_maps>
  normal = normalize((viewMatrix * vec4(normalize(vec3(-nsWater.x, 1.0, -nsWater.y)), 0.0)).xyz);`);
    };
    m.customProgramCacheKey = () => 'water' + (o.hole ? 'h' : '');
    m.needsUpdate = true;
    list.push({ U, deep: o.deep.map(c => col(c)), crest: o.crest.map(c => col(c)) });
    return m;
  }
  const tick = () => {
    T.value = simTime; const n = todState.night;
    list.forEach(w => { w.U.uWDeep.value.copy(w.deep[0]).lerp(w.deep[1], n); w.U.uWCrest.value.copy(w.crest[0]).lerp(w.crest[1], n); });
  };
  return { apply, tick };
})();

// Río bajo los puentes
Water.apply(waterMat, { deep: [0x0b3a52, 0x04101f], crest: [0x2f8f9c, 0x12304a] });

// Charcos y tramos inundados (modo RACE): oleaje pequeño y rápido, sin espuma
{
  const _om = obsMats; let done = false;
  obsMats = function () {
    _om();
    if (done || !OBSM.water) return; done = true;
    [OBSM.water, OBSM.flood].forEach(m => { Water.apply(m, { scale: 4, amp: 0.4, foam: 0, rough: 0.06, env: 1.15, deep: [0x16384a, 0x060d18], crest: [0x3f7f95, 0x16304a] }); });
  };
}

// Mar de Miami: a la izquierda de la carretera, tras la playa
const Sea = (() => {
  const S = { off: { value: new THREE.Vector2() }, SHORE: -40 };
  const mat = envMat(std({ color: 0xffffff }));
  Water.apply(mat, { off: S.off, shore: 350, hole: true, deep: [0x06506e, 0x041423], crest: [0x35c4bd, 0x16405a] });
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(700, SPAN, 8, 110).rotateX(-Math.PI / 2), mat);
  mesh.position.set(S.SHORE - 350, 0.05, WRAP_Z - SPAN / 2); mesh.frustumCulled = false; mesh.visible = false; scene.add(mesh);
  S.mesh = mesh;
  S.world = id => { mesh.visible = City.seaSide = id === 'miami'; };
  S.scroll = d => {
    if (!mesh.visible) return;
    S.off.value.y = (S.off.value.y - d) % 8192; // el oleaje queda fijo al suelo aunque la malla no se mueva
    // el lado del mar no tiene edificios
    BLD.forEach((b, i) => { if (b.x < 0) { setInst(b.mesh, b.mi, b.x, -200, b.z, b.w, b.h, b.d); setInst(roofMesh, i, 0, -50, 0, 0.001, 0.001, 0.001); b.hidden = true; } });
    BMESH.forEach(m => { m.instanceMatrix.needsUpdate = true; }); roofMesh.instanceMatrix.needsUpdate = true;
  };
  return S;
})();
{
  const _sw = scrollWorld;
  scrollWorld = function (d, t) { _sw(d, t); Sea.scroll(d); };
  const _aw = applyWorldNow;
  applyWorldNow = (id, pack) => { _aw(id, pack); Sea.world(id); };
  const _render = Post.render;
  Post.render = () => { Water.tick(); _render(); };
}
